// lib/screens/ai_analysis_detail_screen.dart
import 'package:flutter/material.dart';

import '../widgets/base_scaffold.dart';
import '../theme/app_theme.dart';
import '../ai_analysis/ai_analysis_history.dart';

class AiAnalysisDetailScreen extends StatelessWidget {
  const AiAnalysisDetailScreen({super.key, required this.entry});

  final AiAnalysisHistoryEntry entry;

  String _formatDate(DateTime dt) {
    String two(int v) => v.toString().padLeft(2, '0');
    return '${dt.year}/${two(dt.month)}/${two(dt.day)} ${two(dt.hour)}:${two(dt.minute)}';
  }

  String _pct(double v) => '${(v * 100).toStringAsFixed(1)}%';

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return BaseScaffold(
      title: 'AI分析レポート',
      showBack: true,
      showFooter: false,
      body: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 520),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                // メタ情報カード
                Container(
                  width: double.infinity,
                  padding:
                  const EdgeInsets.symmetric(horizontal: 16, vertical: 14),
                  decoration: BoxDecoration(
                    color: theme.colorScheme.surface,
                    borderRadius: BorderRadius.circular(18),
                    border: Border.all(color: Colors.black12),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        entry.scope == 'overall'
                            ? '対象：全体（すべての分野）'
                            : '対象分野：${entry.targetLabel}',
                        style: theme.textTheme.bodyMedium?.copyWith(
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        '分析日時：${_formatDate(entry.createdAt)}',
                        style: theme.textTheme.bodySmall
                            ?.copyWith(color: AppColors.textSecondary),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        '対象の解答数：${entry.totalAnswers}問　／　正答率：${_pct(entry.accuracy)}',
                        style: theme.textTheme.bodySmall
                            ?.copyWith(color: AppColors.textSecondary),
                      ),
                    ],
                  ),
                ),

                const SizedBox(height: 16),

                // 本文カード
                Container(
                  width: double.infinity,
                  padding:
                  const EdgeInsets.fromLTRB(18, 16, 18, 20),
                  decoration: BoxDecoration(
                    color: theme.colorScheme.surface,
                    borderRadius: BorderRadius.circular(18),
                    border: Border.all(color: Colors.black26),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          const Icon(Icons.insights_rounded,
                              size: 22, color: AppColors.primary),
                          const SizedBox(width: 8),
                          Text(
                            'NurAIの分析レポート',
                            style: theme.textTheme.titleMedium
                                ?.copyWith(fontWeight: FontWeight.w700),
                          ),
                        ],
                      ),
                      const SizedBox(height: 12),
                      Text(
                        entry.body,
                        style: theme.textTheme.bodyMedium?.copyWith(
                          height: 1.5,
                          color: AppColors.textPrimary,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

// lib/screens/ai_analysis_history_screen.dart
import 'package:flutter/material.dart';

import '../widgets/base_scaffold.dart';
import '../theme/app_theme.dart';
import '../ai_analysis/ai_analysis_history.dart';
import 'ai_analysis_detail_screen.dart';

class AiAnalysisHistoryScreen extends StatefulWidget {
  const AiAnalysisHistoryScreen({super.key});

  @override
  State<AiAnalysisHistoryScreen> createState() =>
      _AiAnalysisHistoryScreenState();
}

class _AiAnalysisHistoryScreenState extends State<AiAnalysisHistoryScreen> {
  late Future<List<AiAnalysisHistoryEntry>> _future;

  @override
  void initState() {
    super.initState();
    _future = AiAnalysisHistory.instance.all();
  }

  Future<void> _reload() async {
    setState(() {
      _future = AiAnalysisHistory.instance.all();
    });
    await _future;
  }

  String _formatDate(DateTime dt) {
    String two(int v) => v.toString().padLeft(2, '0');
    return '${dt.year}/${two(dt.month)}/${two(dt.day)} ${two(dt.hour)}:${two(dt.minute)}';
  }

  String _pct(double v) => '${(v * 100).toStringAsFixed(1)}%';

  Future<void> _confirmClearAll() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('履歴をすべて削除しますか？'),
        content: const Text(
          'AI分析の履歴をすべて削除します。この操作は元に戻せません。',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(false),
            child: const Text('キャンセル'),
          ),
          TextButton(
            onPressed: () => Navigator.of(context).pop(true),
            child: const Text(
              '削除する',
              style: TextStyle(color: Colors.red),
            ),
          ),
        ],
      ),
    );

    if (ok == true) {
      await AiAnalysisHistory.instance.clear();
      if (!mounted) return;
      await _reload();
    }
  }

  Future<void> _deleteOne(AiAnalysisHistoryEntry entry) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('この分析を削除しますか？'),
        content: Text(
          '「${entry.targetLabel}」の分析（${_formatDate(entry.createdAt)}）を削除します。',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(false),
            child: const Text('キャンセル'),
          ),
          TextButton(
            onPressed: () => Navigator.of(context).pop(true),
            child: const Text(
              '削除する',
              style: TextStyle(color: Colors.red),
            ),
          ),
        ],
      ),
    );

    if (ok == true) {
      await AiAnalysisHistory.instance.remove(entry.id);
      if (!mounted) return;
      await _reload();
    }
  }

  @override
  Widget build(BuildContext context) {
    return BaseScaffold(
      title: 'AI分析履歴',
      showBack: true,
      showFooter: false,
      actions: [
        IconButton(
          icon: const Icon(Icons.delete_sweep_rounded),
          tooltip: '履歴をすべて削除',
          onPressed: _confirmClearAll,
        ),
      ],
      body: FutureBuilder<List<AiAnalysisHistoryEntry>>(
        future: _future,
        builder: (context, snap) {
          if (snap.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }
          if (snap.hasError) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Text('履歴の読み込みに失敗しました：${snap.error}'),
              ),
            );
          }

          final items = snap.data ?? const <AiAnalysisHistoryEntry>[];
          if (items.isEmpty) {
            return const Center(
              child: Padding(
                padding: EdgeInsets.all(24),
                child: Text(
                  'AI分析の履歴はまだありません。\n\nAI分析画面から分析を実行すると、ここに記録されます。',
                  textAlign: TextAlign.center,
                ),
              ),
            );
          }

          return RefreshIndicator(
            onRefresh: _reload,
            child: ListView.separated(
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
              itemCount: items.length,
              separatorBuilder: (_, __) => const SizedBox(height: 10),
              itemBuilder: (context, index) {
                final e = items[index];
                return InkWell(
                  borderRadius: BorderRadius.circular(14),
                  onTap: () {
                    Navigator.of(context).push(
                      MaterialPageRoute(
                        builder: (_) => AiAnalysisDetailScreen(entry: e),
                      ),
                    );
                  },
                  child: Container(
                    padding: const EdgeInsets.fromLTRB(14, 10, 10, 10),
                    decoration: BoxDecoration(
                      color: Theme.of(context).colorScheme.surface,
                      borderRadius: BorderRadius.circular(14),
                      border: Border.all(color: Colors.black12),
                    ),
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Icon(
                          e.scope == 'overall'
                              ? Icons.analytics_rounded
                              : Icons.task_alt_rounded,
                          color: AppColors.primary,
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                e.scope == 'overall'
                                    ? '全体分析'
                                    : '分野分析：${e.targetLabel}',
                                style: Theme.of(context)
                                    .textTheme
                                    .bodyMedium
                                    ?.copyWith(fontWeight: FontWeight.w700),
                              ),
                              const SizedBox(height: 2),
                              Text(
                                _formatDate(e.createdAt),
                                style: Theme.of(context)
                                    .textTheme
                                    .bodySmall
                                    ?.copyWith(
                                  color: AppColors.textSecondary,
                                ),
                              ),
                              const SizedBox(height: 2),
                              Text(
                                '回答数：${e.totalAnswers}問　／　正答率：${_pct(e.accuracy)}',
                                style: Theme.of(context)
                                    .textTheme
                                    .bodySmall
                                    ?.copyWith(
                                  color: AppColors.textSecondary,
                                ),
                              ),
                            ],
                          ),
                        ),
                        IconButton(
                          icon: const Icon(Icons.delete_outline_rounded),
                          onPressed: () => _deleteOne(e),
                        ),
                      ],
                    ),
                  ),
                );
              },
            ),
          );
        },
      ),
    );
  }
}

// lib/screens/ai_analysis_screen.dart
import 'package:flutter/material.dart';

import '../widgets/base_scaffold.dart';
import '../models/answer_history.dart';
import '../theme/app_theme.dart';

import '../ai_analysis/ai_analysis_models.dart';
import '../ai_analysis/ai_analysis_service.dart';
import '../ai_analysis/ai_analysis_history.dart';
import '../ai_analysis/ai_analysis_prefs.dart';

import 'ai_analysis_detail_screen.dart';
import 'ai_analysis_history_screen.dart';

class AiAnalysisScreen extends StatefulWidget {
  const AiAnalysisScreen({super.key});

  @override
  State<AiAnalysisScreen> createState() => _AiAnalysisScreenState();
}

class _AiAnalysisScreenState extends State<AiAnalysisScreen> {
  late Future<List<AnswerRecord>> _future;

  bool _isAnalyzingOverall = false;
  bool _isAnalyzingDomain = false;

  // 分野選択（必修＋10分野）
  static const List<String> _domainOptions = [
    '必修',
    '人体の構造と機能',
    '疾病の成り立ちと回復の促進',
    '健康支援と社会保障制度',
    '成人看護学',
    '老年看護学',
    '小児看護学',
    '母性看護学',
    '精神看護学',
    '在宅看護論／地域・在宅看護論',
    '看護の統合と実践',
    'その他',
  ];

  String _selectedDomain = '必修';

  @override
  void initState() {
    super.initState();
    _future = AnswerHistory.instance.all();
  }

  Future<void> _reload() async {
    setState(() {
      _future = AnswerHistory.instance.all();
    });
    await _future;
  }

  // ===== 共通の集計ロジック =====

  double _accuracyOf(List<AnswerRecord> items) {
    if (items.isEmpty) return 0.0;
    final correct = items.where((r) => r.isCorrect).length;
    return correct / items.length;
  }

  /// 1問のレコードを「必修＋10分野＋その他」のどれかにマッピングする
  String _domainKeyOfRecord(AnswerRecord r) {
    final buf = StringBuffer();
    buf.write(r.difficulty);
    if (r.domain != null) buf.write(' ${r.domain}');
    if (r.major != null) buf.write(' ${r.major}');
    if (r.mid != null) buf.write(' ${r.mid}');
    if (r.topic != null) buf.write(' ${r.topic}');
    final text = buf.toString();

    // 0) difficulty が「必修問題」なら必修に寄せる
    if (r.difficulty.contains('必修')) {
      return '必修';
    }

    // ① 基礎3分野
    if (text.contains('人体の構造')) {
      return '人体の構造と機能';
    }
    if (text.contains('疾病の成り立ち') || text.contains('回復の促進')) {
      return '疾病の成り立ちと回復の促進';
    }
    if (text.contains('健康支援') || text.contains('社会保障')) {
      return '健康支援と社会保障制度';
    }

    // ② 各看護学分野
    if (text.contains('成人看護')) {
      return '成人看護学';
    }
    if (text.contains('老年看護')) {
      return '老年看護学';
    }
    if (text.contains('小児看護')) {
      return '小児看護学';
    }
    if (text.contains('母性看護')) {
      return '母性看護学';
    }
    if (text.contains('精神看護')) {
      return '精神看護学';
    }
    if (text.contains('在宅看護論') || text.contains('地域・在宅看護')) {
      return '在宅看護論／地域・在宅看護論';
    }
    if (text.contains('統合と実践') || text.contains('看護の統合')) {
      return '看護の統合と実践';
    }

    // ③ どれにも当てはまらなければその他
    return 'その他';
  }

  Map<String, _DomainAgg> _aggregateByDomain(List<AnswerRecord> items) {
    final map = <String, _DomainAgg>{};
    for (final r in items) {
      final key = _domainKeyOfRecord(r);
      final agg = map.putIfAbsent(key, () => _DomainAgg.empty(key));
      agg.total += 1;
      if (r.isCorrect) agg.correct += 1;
    }

    // 存在しない分野も0で用意しておく（UIの並びを固定）
    for (final name in _domainOptions) {
      map.putIfAbsent(name, () => _DomainAgg.empty(name));
    }

    return map;
  }

  String _pct(double v) => '${(v * 100).toStringAsFixed(1)}%';

  // ===== AI分析 → 履歴保存 → 詳細画面へ遷移 =====

  Future<void> _runOverallAnalysis(List<AnswerRecord> records) async {
    if (records.isEmpty) return;

    setState(() => _isAnalyzingOverall = true);
    try {
      final result = await AiAnalysisService.analyzeOverall(
        records: records,
        tone: await AiAnalysisPrefs.getTone(),
      );

      final accAll = _accuracyOf(records);
      final body = _buildFullBody(result);

      final entry = AiAnalysisHistoryEntry(
        id: DateTime.now().millisecondsSinceEpoch.toString(),
        createdAt: DateTime.now(),
        scope: 'overall',
        targetLabel: '全体',
        totalAnswers: result.totalAnswers,
        accuracy: accAll,
        body: body,
      );

      await AiAnalysisHistory.instance.add(entry);

      if (!mounted) return;
      Navigator.of(context).push(
        MaterialPageRoute(
          builder: (_) => AiAnalysisDetailScreen(entry: entry),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('AI分析中にエラーが発生しました：$e')),
      );
    } finally {
      if (mounted) {
        setState(() => _isAnalyzingOverall = false);
      }
    }
  }

  Future<void> _runDomainAnalysis(
      List<AnswerRecord> records, String domainKey) async {
    final byDomain = _aggregateByDomain(records);
    final agg = byDomain[domainKey] ?? _DomainAgg.empty(domainKey);

    if (agg.total == 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('「$domainKey」の解答履歴がまだありません。')),
      );
      return;
    }

    if (agg.total < 5) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
              '「$domainKey」のAI分析には、少なくとも5問以上の解答があると安定します。（現在: ${agg.total}問）'),
        ),
      );
    }

    final filtered =
    records.where((r) => _domainKeyOfRecord(r) == domainKey).toList();
    if (filtered.isEmpty) return;

    setState(() => _isAnalyzingDomain = true);
    try {
      final result = await AiAnalysisService.analyzeOverall(
        records: filtered,
        tone: await AiAnalysisPrefs.getTone(),
      );

      final acc = _accuracyOf(filtered);
      final body = _buildFullBody(result);

      final entry = AiAnalysisHistoryEntry(
        id: DateTime.now().millisecondsSinceEpoch.toString(),
        createdAt: DateTime.now(),
        scope: 'domain',
        targetLabel: domainKey,
        totalAnswers: result.totalAnswers,
        accuracy: acc,
        body: body,
      );

      await AiAnalysisHistory.instance.add(entry);

      if (!mounted) return;
      Navigator.of(context).push(
        MaterialPageRoute(
          builder: (_) => AiAnalysisDetailScreen(entry: entry),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('分野別AI分析中にエラーが発生しました：$e')),
      );
    } finally {
      if (mounted) {
        setState(() => _isAnalyzingDomain = false);
      }
    }
  }

  /// 旧UIと同様の構成で、AiAnalysisResult から本文テキストを組み立てる
  String _buildFullBody(AiAnalysisResult r) {
    final buf = StringBuffer();

    buf.writeln('【出題形式ごとの傾向】');
    buf.writeln(r.difficultyComment);
    buf.writeln();
    buf.writeln('【分野別の強みと課題】');
    buf.writeln(r.domainComment);
    buf.writeln();
    buf.writeln('【これからの学び方の提案】');
    buf.writeln(r.studyAdvice);
    buf.writeln();
    buf.writeln('【NurAIからのひとこと】');
    buf.writeln(r.nuraiComment);

    return buf.toString().trimRight();
  }

  // ===== UI =====

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    return BaseScaffold(
      title: 'AI分析',
      showBack: false,
      showFooter: false,
      actions: [
        IconButton(
          icon: const Icon(Icons.history_rounded),
          tooltip: '分析履歴を見る',
          onPressed: () {
            Navigator.of(context).push(
              MaterialPageRoute(
                builder: (_) => const AiAnalysisHistoryScreen(),
              ),
            );
          },
        ),
      ],
      body: FutureBuilder<List<AnswerRecord>>(
        future: _future,
        builder: (context, snap) {
          if (snap.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }
          if (snap.hasError) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Text('解答履歴の読み込みに失敗しました：${snap.error}'),
              ),
            );
          }

          final records = snap.data ?? const <AnswerRecord>[];
          final total = records.length;
          final accAll = _accuracyOf(records);

          final now = DateTime.now();
          final from7d = now.subtract(const Duration(days: 7));
          final recent7d = records.where((r) => r.ts.isAfter(from7d)).toList();
          final accRecent7d = _accuracyOf(recent7d);

          final byDomainAgg = _aggregateByDomain(records);

          return RefreshIndicator(
            onRefresh: _reload,
            child: SingleChildScrollView(
              physics: const AlwaysScrollableScrollPhysics(),
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
              child: Center(
                child: ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 520),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      // コンセプトカード
                      _conceptCard(theme, total),

                      const SizedBox(height: 20),

                      // ★ 「全体をAI分析」ボタン（サマリカードより上）
                      SizedBox(
                        width: double.infinity,
                        height: 52,
                        child: ElevatedButton.icon(
                          style: AppStyles.ctaButton(context),
                          icon: _isAnalyzingOverall
                              ? const SizedBox(
                            width: 18,
                            height: 18,
                            child: CircularProgressIndicator(
                              strokeWidth: 2,
                              valueColor: AlwaysStoppedAnimation<Color>(
                                  Colors.white),
                            ),
                          )
                              : const Icon(Icons.auto_awesome_rounded),
                          label: Text(
                            _isAnalyzingOverall
                                ? '全体を分析中...'
                                : 'NurAIに全体の学習状況を分析してもらう',
                          ),
                          onPressed: _isAnalyzingOverall || records.isEmpty
                              ? null
                              : () => _runOverallAnalysis(records),
                        ),
                      ),

                      const SizedBox(height: 16),

                      // サマリカード（総合）
                      _summaryRow(theme, total, accAll, recent7d.length,
                          accRecent7d),

                      const SizedBox(height: 24),

                      // 分野ごとの分析セクション
                      Text(
                        '分野ごとのAI分析',
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w700),
                      ),
                      const SizedBox(height: 8),
                      Text(
                        '必修や成人看護学など、特定の分野にフォーカスして分析します。',
                        style: theme.textTheme.bodySmall
                            ?.copyWith(color: AppColors.textSecondary),
                      ),

                      const SizedBox(height: 16),

                      // ★ 分野選択 + 分析ボタン（カードの上に移動）
                      Row(
                        children: [
                          Expanded(
                            child: DropdownButtonFormField<String>(
                              value: _selectedDomain,
                              isExpanded: true, // ★ 追加：内部のRowを幅いっぱいにして縮めやすくする
                              decoration: const InputDecoration(
                                labelText: '分析したい分野',
                                border: OutlineInputBorder(),
                                isDense: true,
                              ),
                              items: _domainOptions
                                  .map(
                                    (d) => DropdownMenuItem<String>(
                                  value: d,
                                  child: Text(
                                    d,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis, // ★ 長い文は「…」で省略
                                  ),
                                ),
                              )
                                  .toList(),
                              onChanged: (val) {
                                if (val == null) return;
                                setState(() => _selectedDomain = val);
                              },
                            ),
                          ),
                          const SizedBox(width: 8),
                          SizedBox(
                            height: 52,
                            child: ElevatedButton(
                              style: ElevatedButton.styleFrom(
                                padding: const EdgeInsets.symmetric(horizontal: 14),
                              ),
                              onPressed: _isAnalyzingDomain || records.isEmpty
                                  ? null
                                  : () => _runDomainAnalysis(records, _selectedDomain),
                              child: _isAnalyzingDomain
                                  ? const SizedBox(
                                width: 18,
                                height: 18,
                                child: CircularProgressIndicator(
                                  strokeWidth: 2,
                                  valueColor: AlwaysStoppedAnimation<Color>(Colors.white),
                                ),
                              )
                                  : const Text('分野を分析'),
                            ),
                          ),
                        ],
                      ),

                      const SizedBox(height: 16),

                      // 分野別回答数カード（Wrap）
                      _domainCards(byDomainAgg),

                      const SizedBox(height: 16),

                      if (records.isEmpty)
                        Text(
